mapper.select:
select
from Project_Cp_Experience cpe left join Project_Cp_Dtl cpd on cpd.Cpd_Id=cpe.Cpd_Id left join Project_Cp cp on cp.Cp_Id=cpd.Cp_Id left join Pre_Project pro on pro.P_ID=cp.P_ID
and cpe.Te_Id = #{params.teId}
and cpe.Cpd_Id=#{params.cpdId}
and cp.P_ID=#{params.pId}
and likePname(#{params.pName},pro.P_ID)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and likePname(#{params.cpeContent},pro.P_ID)=true
and pro.P_Name like concat('%',#{params.cpeContent},'%')
and cpd.Cpd_Name like concat('%',#{params.cpdName},'%')
and cpe.Cpe_Create_Uname like concat('%',#{params.cpeCreateUname},'%')
order by cpe.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by cpe.Cpe_Create_Time desc
